// Seguro: o comando e o valor viajam separados
export async function buscarClientePorEmail(email) {
  const { rows } = await pool.query(
    "SELECT id, nome FROM clientes WHERE email = $1",
    [email]
  );
  return rows[0] ?? null;
}

const COLUNAS = new Map([["nome", "nome"], ["cadastro", "criado_em"]]);
const DIRECOES = new Map([["asc", "ASC"], ["desc", "DESC"]]);

export async function listarClientes({ ordem, direcao, limite = 50 }) {
  const coluna = COLUNAS.get(ordem) ?? "nome";
  const sentido = DIRECOES.get(direcao) ?? "ASC";
  const { rows } = await pool.query(
    `SELECT id, nome FROM clientes ORDER BY ${coluna} ${sentido} LIMIT $1`,
    [Math.min(Number(limite) || 50, 100)]
  );
  return rows;
}

