import bcrypt from "bcrypt";

const CUSTO = 12; // ajuste ao que o seu servidor aguenta, nunca abaixo de 10

export async function gerarHashSenha(senha) {
  if (Buffer.byteLength(senha, "utf8") > 72) {
    throw new Error("A senha pode ter no máximo 72 bytes");
  }
  return bcrypt.hash(senha, CUSTO); // o sal é gerado e embutido no resultado
}

export async function conferirSenha(senha, hashSalvo) {
  return bcrypt.compare(senha, hashSalvo); // compara em tempo constante
}

import argon2 from "argon2";
import bcrypt from "bcrypt";

const PARAMS = { type: argon2.argon2id, memoryCost: 19456, timeCost: 2, parallelism: 1 };

export const gerarHash = (senha) => argon2.hash(senha, PARAMS);

export async function entrar(conta, senha) {
  const ehBcrypt = conta.hashSenha.startsWith("$2");
  const ok = ehBcrypt
    ? await bcrypt.compare(senha, conta.hashSenha)
    : await argon2.verify(conta.hashSenha, senha);
  if (ok && ehBcrypt) {
    await salvarHash(conta.id, await gerarHash(senha)); // migra sem pedir nada
  }
  return ok;
}

import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

const chave = Buffer.from(process.env.CHAVE_DADOS_B64 ?? "", "base64");
if (chave.length !== 32) throw new Error("CHAVE_DADOS_B64 precisa ter 32 bytes");

export function cifrar(texto) {
  const iv = randomBytes(12); // nunca reutilize um IV com a mesma chave
  const cifra = createCipheriv("aes-256-gcm", chave, iv);
  const dados = Buffer.concat([cifra.update(texto, "utf8"), cifra.final()]);
  const tag = cifra.getAuthTag();
  return [iv, tag, dados].map((b) => b.toString("base64")).join(".");
}

export function decifrar(guardado) {
  const [iv, tag, dados] = guardado.split(".").map((p) => Buffer.from(p, "base64"));
  const decifra = createDecipheriv("aes-256-gcm", chave, iv);
  decifra.setAuthTag(tag); // se o valor foi alterado, final() lança erro
  return Buffer.concat([decifra.update(dados), decifra.final()]).toString("utf8");
}

import { createHmac } from "node:crypto";

const chaveIndice = Buffer.from(process.env.CHAVE_INDICE_B64 ?? "", "base64");

export function indiceCpf(cpf) {
  const normalizado = cpf.replace(/\D/g, "");
  return createHmac("sha256", chaveIndice).update(normalizado).digest("hex");
}

